package com.melon.melonmart.controller;
import com.google.gson.Gson; import com.melon.melonmart.dao.WishlistDAO; import com.melon.melonmart.model.User; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException; import java.util.*;
@WebServlet("/api/wishlist") public class WishlistServlet extends HttpServlet{private final WishlistDAO dao=new WishlistDAO();private final Gson gson=new Gson();private User u(HttpServletRequest r){HttpSession s=r.getSession(false);Object x=s==null?null:s.getAttribute("user");return x instanceof User?(User)x:null;}private void json(HttpServletResponse r,Object x)throws IOException{r.setContentType("application/json");r.setCharacterEncoding("UTF-8");r.getWriter().write(gson.toJson(x));}
protected void doGet(HttpServletRequest r,HttpServletResponse p)throws IOException{User x=u(r);if(x==null){p.sendError(401,"Please login first");return;}json(p,dao.getWishlistProducts(x.getId()));}
protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{User x=u(r);if(x==null){p.sendError(401,"Please login first");return;}String a=r.getParameter("action"),id=r.getParameter("productId");boolean ok;if("clear".equals(a))ok=dao.clearWishlist(x.getId());else{if(id==null){p.sendError(400,"Product ID is required");return;}try{int pid=Integer.parseInt(id);if("add".equals(a))ok=dao.addToWishlist(x.getId(),pid);else if("remove".equals(a))ok=dao.removeFromWishlist(x.getId(),pid);else{p.sendError(400,"Invalid wishlist action");return;}}catch(NumberFormatException e){p.sendError(400,"Invalid product ID");return;}}Map<String,Object> m=new HashMap<>();m.put("success",ok);json(p,m);}}
